package org.eclipse.kura.core.keystore.crl.test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.security.cert.CertStore;
import java.security.cert.CollectionCertStoreParameters;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Date;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.TimeUnit;

import org.bouncycastle.asn1.x500.X500Name;
import org.eclipse.kura.core.testutil.pki.TestCA;
import org.eclipse.kura.core.testutil.pki.TestCA.CRLCreationOptions;
import org.eclipse.kura.core.testutil.pki.TestCA.CertificateCreationOptions;
import org.junit.Test;

public class CrlConcurrentAccessTest extends CrlKeystoreServiceTestBase {

    private static final int CRL_COUNT = 40;
    private static final int READER_COUNT = 4;
    private static final long UPDATE_TIMEOUT_MS = TimeUnit.SECONDS.toMillis(60);

    private final List<String> crlUrls = new ArrayList<>();
    private final List<Throwable> readerErrors = new CopyOnWriteArrayList<>();

    @Test
    public void crlsAndCrlStoreCanBeReadWhileTheCacheIsUpdated() throws Exception {
        givenCrlsPublishedAtDistinctUrls(CRL_COUNT);
        givenKeystoreServiceDownloadingThePublishedCrls();

        whenCrlsAreReadConcurrentlyUntilAllAreServed();

        thenNoReaderFailed();
        thenKeystoreServesCrls(CRL_COUNT);
    }

    private void givenCrlsPublishedAtDistinctUrls(final int count) throws Exception {
        final TestCA ca = new TestCA(CertificateCreationOptions.builder(new X500Name("cn=Test CA, dc=bar.com")).build());

        for (int i = 0; i < count; i++) {
            final CRLCreationOptions options = CRLCreationOptions.builder()
                    .withStartDate(Date.from(Instant.now().minusSeconds(60L + i)))
                    .withEndDate(Date.from(Instant.now().plusSeconds(3600))).build();

            this.crlUrls.add(writeCrlFile("crl" + i + ".crl", ca.generateCRL(options)).toURI().toString());
        }
    }

    private void givenKeystoreServiceDownloadingThePublishedCrls() throws Exception {
        final Map<String, Object> options = new HashMap<>();
        options.put("crl.urls", this.crlUrls.toArray(new String[0]));
        options.put("verify.crl", false);

        givenKeystoreServiceWithCrlManagement(options);
    }

    private void whenCrlsAreReadConcurrentlyUntilAllAreServed() throws InterruptedException {
        final long deadline = System.currentTimeMillis() + UPDATE_TIMEOUT_MS;
        final List<Thread> readers = new ArrayList<>();

        for (int i = 0; i < READER_COUNT; i++) {
            final Thread reader = new Thread(() -> readCrlsUntil(deadline));
            readers.add(reader);
            reader.start();
        }

        for (final Thread reader : readers) {
            reader.join();
        }
    }

    private void readCrlsUntil(final long deadline) {
        try {
            while (System.currentTimeMillis() < deadline) {
                final CertStore certStore = this.keystoreService.getCRLStore();
                final CollectionCertStoreParameters parameters = (CollectionCertStoreParameters) certStore
                        .getCertStoreParameters();

                int iterated = 0;
                for (final Object crl : parameters.getCollection()) {
                    iterated += crl != null ? 1 : 0;
                }

                certStore.getCRLs(null);

                if (iterated == CRL_COUNT && this.keystoreService.getCRLs().size() == CRL_COUNT) {
                    return;
                }
            }
        } catch (final Exception e) {
            this.readerErrors.add(e);
        }
    }

    private void thenNoReaderFailed() {
        assertTrue("readers failed: " + this.readerErrors, this.readerErrors.isEmpty());
    }

    private void thenKeystoreServesCrls(final int expectedCount) throws Exception {
        assertEquals(expectedCount, this.keystoreService.getCRLs().size());
        assertEquals(expectedCount, this.keystoreService.getCRLStore().getCRLs(null).size());
    }
}
